const int xPin = {{x_pin}};
const int yPin = {{y_pin}};
const int swPin = {{sw_pin}};
const int deadzone = {{deadzone}};
const int center = 512;

void setup() {
  Serial.begin(115200);
  pinMode(swPin, INPUT_PULLUP);
}

int applyDeadzone(int v) {
  int d = v - center;
  if (abs(d) < deadzone) return 0;
  return d;
}

void loop() {
  int x = applyDeadzone(analogRead(xPin));
  int y = applyDeadzone(analogRead(yPin));
  int sw = digitalRead(swPin) == LOW ? 1 : 0;
  Serial.print("x="); Serial.print(x);
  Serial.print(" y="); Serial.print(y);
  Serial.print(" sw="); Serial.println(sw);
  delay(50);
}
